    // B is NK x NJ in C:      B[k][j]
    //   -> Halide Buffer B(j, k) with shape (nj, nk)
    // C is NJ x NL in C:      C[j][l]
    //   -> Halide Buffer C(l, j) with shape (nl, nj)
    // D is NI x NL in C:      D[i][l]
    //   -> Halide Buffer D(l, i) with shape (nl, ni)

