    // A[i][k] = (DATA_TYPE) ((i*k+1) % ni) / ni;
    // A(k, i) in Halide
    init_A(k, i) = cast<num_t>((i * k + 1) % ni) / cast<int>(ni);

    // B[i][j] = (DATA_TYPE) (i*(j+1) % nj) / nj;
    // B(j, k) in Halide, where k is original 'i' and j is original 'j'
