    // C[i][j] = (DATA_TYPE) ((i*(j+3)+1) % nl) / nl;
    // C(l, j) in Halide, where j is original 'i' and l is original 'j'
    init_C(l, j) = cast<num_t>((j * (l + 3) + 1) % nl) / cast<int>(nl);

    // D[i][j] = (DATA_TYPE) (i*(j+2) % nk) / nk;
    // D(l, i) in Halide, where i is original 'i' and l is original 'j'
    init_D(l, i) = cast<num_t>((i * (l + 2)) % nk) / cast<int>(nk);

    init_A.realize(A);
    init_B.realize(B);
    init_C.realize(C);
    init_D.realize(D);
}

