    // Problem sizes from PolyBench / 2mm.hpp
    int ni = NI;
    int nj = NJ;
    int nk = NK;
    int nl = NL;

    // Scalars
    num_t alpha;
    num_t beta;

    // Buffers corresponding to the original C arrays.
    //
    // Original C shapes:
    //   A[NI][NK], B[NK][NJ], C[NJ][NL], D[NI][NL], tmp[NI][NJ]
    //
    // Halide Buffers (first dimension is fastest-varying):
    //   A(k, i)   -> (nk, ni)
    //   B(j, k)   -> (nj, nk)
    //   C(l, j)   -> (nl, nj)
    //   D(l, i)   -> (nl, ni)
    //   tmp(j, i) -> (nj, ni)
    Halide::Buffer<num_t, 2> A_buf(nk, ni);
    Halide::Buffer<num_t, 2> B_buf(nj, nk);
    Halide::Buffer<num_t, 2> C_buf(nl, nj);
    Halide::Buffer<num_t, 2> D_buf(nl, ni);
    Halide::Buffer<num_t, 2> tmp_buf(nj, ni);

    // Initialize A, B, C, D and the scalars alpha, beta.
    init_array(ni, nj, nk, nl, &alpha, &beta,
               A_buf, B_buf, C_buf, D_buf);

    // ImageParams to pass Buffers into Halide Funcs.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");
    ImageParam C_param(type_of<num_t>(), 2, "C_param");
    ImageParam D_param(type_of<num_t>(), 2, "D_param");
    ImageParam tmp_param(type_of<num_t>(), 2, "tmp_param");

