    B_param.set(B_buf);
    C_param.set(C_buf);
    D_param.set(D_buf);
    tmp_param.set(tmp_buf);

    // Vars and reduction domains.
    Var i("i"), j("j"), l("l");
    RDom k_ab(0, nk, "k_ab"); // reduction over NK
    RDom k_bc(0, nj, "k_bc"); // reduction over NJ

    // Stage 1: tmp(i,j) = sum_k alpha * A(i,k) * B(k,j)
    // In Halide coordinates: tmp(j, i), A_param(k, i), B_param(j, k)
    Func tmp("tmp");

    tmp(j, i) = cast<num_t>(0);
    tmp(j, i) += Expr(alpha) * A_param(k_ab, i) * B_param(j, k_ab);

    // Stage 2: D(i,l) = beta * D(i,l) + sum_k tmp(i,k) * C(k,l)
    // In Halide coordinates: D(l, i), tmp(k, i), C(l, k)
    Func D_updated("D_updated");

    D_updated(l, i) = Expr(beta) * D_param(l, i);
    D_updated(l, i) += tmp_param(k_bc, i) * C_param(l, k_bc);

    // Schedule: compute tmp fully, then D, matching the sequential nature
    // of the original C kernel.
    tmp.compute_root();
    D_updated.compute_root();

    // Compile both stages ahead of timing.
    tmp.compile_jit();
    D_updated.compile_jit();

    // Time the kernel: first compute tmp, then update D.
    auto start = std::chrono::high_resolution_clock::now();

    // Stage 1: tmp = alpha * A * B
    tmp.realize(tmp_buf);

    // Stage 2: D = alpha * A * B * C + beta * D
    D_updated.realize(D_buf);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the resulting D for debugging / DCE prevention.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
