#include "2mm.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

// ---------------------------------------------------------------------
// Initialize input arrays using Halide Funcs, mimicking the C version.
// ---------------------------------------------------------------------
static void init_array(int ni, int nj, int nk, int nl,
                       num_t *alpha,
                       num_t *beta,
                       Halide::Buffer<num_t, 2> A,
                       Halide::Buffer<num_t, 2> B,
                       Halide::Buffer<num_t, 2> C,
                       Halide::Buffer<num_t, 2> D) {
    *alpha = (num_t)1.5;
    *beta  = (num_t)1.2;

    // Vars for initialization
    Var i("i"), j("j"), k("k"), l("l");

    // A is NI x NK in C, accessed as A[i][j].
    // In Halide we use a Buffer of size (NK, NI) and access as A(j, i).
    // C code: A[i][j] = ( (i*j + 1) % ni ) / ni;
    Func init_A("init_A");
    init_A(k, i) = cast<num_t>((i * k + 1) % ni) / cast<int>(ni);

    // B is NK x NJ in C, accessed as B[i][j].
    // Halide Buffer: (NJ, NK), access as B(j, i) = B[j][i]_C.
    // C code: B[i][j] = ( i * (j+1) % nj ) / nj;
    Func init_B("init_B");
    init_B(j, k) = cast<num_t>((k * (j + 1)) % nj) / cast<int>(nj);

    // C is NJ x NL in C, accessed as C[i][j].
    // Halide Buffer: (NL, NJ), access as C(j, i) = C[i][j]_C.
    // C code: C[i][j] = ( (i*(j+3) + 1) % nl ) / nl;
    Func init_C("init_C");
    init_C(l, j) = cast<num_t>((j * (l + 3) + 1) % nl) / cast<int>(nl);

    // D is NI x NL in C, accessed as D[i][j].
    // Halide Buffer: (NL, NI), access as D(j, i) = D[i][j]_C.
    // C code: D[i][j] = ( i * (j+2) % nk ) / nk;
    Func init_D("init_D");
    init_D(l, i) = cast<num_t>((i * (l + 2)) % nk) / cast<int>(nk);

    // Realize into the provided Buffers
    init_A.realize(A);
    init_B.realize(B);
    init_C.realize(C);
    init_D.realize(D);
}

int main(int argc, char *argv[]) {
    // Problem sizes
    int ni = NI;
    int nj = NJ;
    int nk = NK;
    int nl = NL;

    // Scalar parameters
    num_t alpha;
    num_t beta;

    // Buffers that correspond to the C arrays.
    //
    // C layout: A[NI][NK]  => Halide: A(k, i) with size (NK, NI)
    //           B[NK][NJ]  => Halide: B(j, k) with size (NJ, NK)
    //           C[NJ][NL]  => Halide: C(l, j) with size (NL, NJ)
    //           D[NI][NL]  => Halide: D(l, i) with size (NL, NI)
    //
    // tmp[NI][NJ] is an internal intermediate; we will model it as a Func.
    Halide::Buffer<num_t, 2> A(nk, ni);
    Halide::Buffer<num_t, 2> B(nj, nk);
    Halide::Buffer<num_t, 2> C(nl, nj);
    Halide::Buffer<num_t, 2> D(nl, ni);

    // Initialize arrays
    init_array(ni, nj, nk, nl, &alpha, &beta, A, B, C, D);

    // -----------------------------------------------------------------
    // Set up the Halide pipeline for the kernel:
    //
    //   /* D := alpha*A*B*C + beta*D */
    //
    //   First:
    //     tmp[i][j] = 0;
    //     for k
    //       tmp[i][j] += alpha * A[i][k] * B[k][j];
    //
    //   Then:
    //     D[i][j] *= beta;
    //     for k
    //       D[i][j] += tmp[i][k] * C[k][j];
    // -----------------------------------------------------------------

    // ImageParams for inputs (2D matrices).
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");
    ImageParam C_param(type_of<num_t>(), 2, "C_param");
    ImageParam D_param(type_of<num_t>(), 2, "D_param");

    // Bind ImageParams to the Buffers.
    A_param.set(A);
    B_param.set(B);
    C_param.set(C);
    D_param.set(D);

    // Vars
    Var i("i"), j("j");

    // First GEMM stage: tmp = alpha * A * B
    //
    // C indices: tmp[i][j]; i in [0,ni), j in [0,nj)
    // Halide: tmp(j, i) with size (NJ, NI)
    Func tmp("tmp");
    RDom k1(0, A_param.dim(0).extent(), "k1");  // k1 in [0, nk)

    // Initialization (tmp[i][j] = 0)
    tmp(j, i) = cast<num_t>(0);

    // Accumulation (tmp[i][j] += alpha * A[i][k] * B[k][j])
    // A[i][k] -> A_param(k1, i)
    // B[k][j] -> B_param(j, k1)
    tmp(j, i) += Expr(alpha) * A_param(k1, i) * B_param(j, k1);

    // Second GEMM-like stage: D = beta * D + tmp * C
    //
    // C indices: D[i][j]; i in [0,ni), j in [0,nl)
    // Halide: D_func(j, i) with size (NL, NI)
    Func D_func("D_func");
    RDom k2(0, B_param.dim(0).extent(), "k2");  // k2 in [0, nj)

    // D[i][j] *= beta
    // D[i][j] -> D_param(j, i)
    D_func(j, i) = Expr(beta) * D_param(j, i);

    // D[i][j] += tmp[i][k] * C[k][j]
    // tmp[i][k] -> tmp(k2, i)
    // C[k][j]   -> C_param(j, k2)
    D_func(j, i) += tmp(k2, i) * C_param(j, k2);

    // -----------------------------------------------------------------
    // Schedule
    // -----------------------------------------------------------------

    // Compute tmp fully before D, as in the original C code.
    tmp.compute_root();

    // Make the traversal order explicit (though this matches defaults).
    // For tmp:
    //   Pure stage: for i in 0..ni-1, for j in 0..nj-1
    //   Update:     for i in 0..ni-1, for k in 0..nk-1, for j in 0..nj-1
    tmp.reorder(j, i);
    tmp.update().reorder(j, k1, i);

    // For D_func:
    //   Pure stage: for i in 0..ni-1, for j in 0..nl-1
    //   Update:     for i in 0..ni-1, for k in 0..nj-1, for j in 0..nl-1
    D_func.reorder(j, i);
    D_func.update().reorder(j, k2, i);

    // Compile the pipeline
    D_func.compile_jit();

    // -----------------------------------------------------------------
    // Execute and time
    // -----------------------------------------------------------------
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: realize D_func into D (in-place update semantics)
    D_func.realize(D);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // -----------------------------------------------------------------
    // Print results (to prevent dead-code elimination and enable checking)
    // -----------------------------------------------------------------
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < ni; ii++) {
            for (int jj = 0; jj < nl; jj++) {
                // D[ii][jj] in C is D(jj, ii) in Halide
                std::cerr << D(jj, ii) << '\n';
            }
        }
    }

    // Print execution time in seconds
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
