    // C[i][j] = (DATA_TYPE) ((i*(j+3)+1) % nl) / nl;
    // C is nj x nl  -> Buffer C(nl, nj) -> C(j, i)
    init_C(j, i) = cast<num_t>((i * (j + 3) + 1) % nl) / cast<int>(nl);

    // Original C:
    // D[i][j] = (DATA_TYPE) (i*(j+2) % nk) / nk;
    // D is ni x nl  -> Buffer D(nl, ni) -> D(j, i)
    init_D(j, i) = cast<num_t>(i * (j + 2) % nk) / cast<int>(nk);

    init_A.realize(A);
    init_B.realize(B);
    init_C.realize(C);
    init_D.realize(D);
}

int main(int argc, char *argv[]) {
    // Problem sizes.
    int ni = NI;
    int nj = NJ;
    int nk = NK;
    int nl = NL;

    // Scalars.
    num_t alpha;
    num_t beta;

    // Buffers (note: Halide uses column-major indexing: (x, y) = (col, row)).
    // A: ni x nk  -> Buffer A(nk, ni)
    // B: nk x nj  -> Buffer B(nj, nk)
    // C: nj x nl  -> Buffer C(nl, nj)
    // D: ni x nl  -> Buffer D(nl, ni)
    Halide::Buffer<num_t, 2> A(nk, ni);
    Halide::Buffer<num_t, 2> B(nj, nk);
    Halide::Buffer<num_t, 2> C(nl, nj);
    Halide::Buffer<num_t, 2> D(nl, ni);

    // Initialize data.
    init_array(ni, nj, nk, nl, &alpha, &beta, A, B, C, D);

    // ImageParams for the kernel.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");
    ImageParam C_param(type_of<num_t>(), 2, "C_param");
    ImageParam D_param(type_of<num_t>(), 2, "D_param");

    A_param.set(A);
    B_param.set(B);
    C_param.set(C);
    D_param.set(D);

    // Vars and reduction domains.
    Var i("i"), j("j");
    // A has extent nk in dim 0.
    RDom k1(0, A.dim(0).extent(), "k1");      // 0 .. nk-1
    // B has extent nj in dim 0.
    RDom k2(0, B.dim(0).extent(), "k2");      // 0 .. nj-1

    // Funcs for the computation.
    // tmp: ni x nj  -> tmp(j, i)
    Func tmp("tmp");
    // two_mm: final D, ni x nl  -> two_mm(j, i)
    Func two_mm("two_mm");

    // First phase: tmp = alpha * A * B
    // Original C:
    // for i in 0..ni-1
    //   for j in 0..nj-1
    //     tmp[i][j] = 0;
    //     for k in 0..nk-1
    //       tmp[i][j] += alpha * A[i][k] * B[k][j];
    tmp(j, i) = cast<num_t>(0);
    tmp(j, i) += Expr(alpha) * A_param(k1, i) * B_param(j, k1);

    // Second phase: D = beta * D + tmp * C
    // Original C:
    // for i in 0..ni-1
    //   for j in 0..nl-1
    //     D[i][j] *= beta;
    //     for k in 0..nj-1
    //       D[i][j] += tmp[i][k] * C[k][j];
    two_mm(j, i) = Expr(beta) * D_param(j, i);
    two_mm(j, i) += tmp(k2, i) * C_param(j, k2);

    // Simple schedule reflecting the original loop structure.
    tmp.reorder(j, i);
    tmp.update().reorder(j, k1, i);

    two_mm.reorder(j, i);
    two_mm.update().reorder(j, k2, i);

    // JIT-compile the kernel.
    two_mm.compile_jit();

    // Measure execution time of the kernel.
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: result overwrites D.
    two_mm.realize(D);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print out the result matrix D.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i_row = 0; i_row < ni; i_row++) {
            for (int j_col = 0; j_col < nl; j_col++) {
                // D is stored as D(j, i).
                std::cerr << D(j_col, i_row) << '\n';
            }
        }
    }

    // Print elapsed time in seconds.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
