int main(int argc, char *argv[]) {
    // Problem sizes from Polybench
    int ni = NI;
    int nj = NJ;
    int nk = NK;
    int nl = NL;

    // Scalars
    num_t alpha;
    num_t beta;

    // Buffers:
    // We follow the same mapping convention as in the GEMM example:
    // For a C array M[Rows][Cols] accessed as M[i][j],
    // we use Buffer M(Cols, Rows) and access M(j, i).
    Buffer<num_t, 2> A(nk, ni); // A[i][k] -> A(k, i)
    Buffer<num_t, 2> B(nj, nk); // B[k][j] -> B(j, k)
    Buffer<num_t, 2> C(nl, nj); // C[k][j] -> C(j, k)
    Buffer<num_t, 2> D(nl, ni); // D[i][j] -> D(j, i)

    // Initialize data.
    init_array(ni, nj, nk, nl, &alpha, &beta, A, B, C, D);

    // ImageParams corresponding to the buffers.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");
    ImageParam C_param(type_of<num_t>(), 2, "C_param");
    ImageParam D_param(type_of<num_t>(), 2, "D_param");

    A_param.set(A);
    B_param.set(B);
    C_param.set(C);
    D_param.set(D);

    // Halide Vars
    Var i("i"), j("j"), l("l");

    // First multiplication: tmp = alpha * A * B
    // tmp is logically (ni x nj), we store it as tmp(j, i).
    RDom k1(0, A.dim(0).extent(), "k1"); // iterate over k in [0, nk)
    Func tmp("tmp");
    tmp(j, i) = cast<num_t>(0);
    tmp(j, i) += Expr(alpha) * A_param(k1, i) * B_param(j, k1);

    // Second multiplication and accumulation:
    // D := beta * D + tmp * C
    // D is logically (ni x nl), stored as D(l, i).
    // tmp(i,k) * C(k,j) -> tmp(k, i) * C(j, k) with our layout.
    RDom k2(0, C.dim(1).extent(), "k2"); // iterate over k in [0, nj)
    Func d("d");

    d(l, i) = Expr(beta) * D_param(l, i);
    d(l, i) += tmp(k2, i) * C_param(l, k2);

    // Basic schedules that reflect the original loop ordering.
    // First stage: i outer, j inner, k innermost.
    tmp.reorder(j, i);
    tmp.update().reorder(j, k1, i);

